INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "宋史·巻二百六十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/18e8cdf6c086e5a20bcb7a3069fc49c3f0352eb3/content/books/zizhi-tongjian/vol-294/year-0959/part-04/sources/library/songshi-263-douyi-snow-embassy/source.txt", "note": "《宋史》巻二百六十三，段落 songshi-9c6e46fee832-p058260；EPUB电子本，纸本及异文待核", "id": "82977823-854f-5c27-bc70-61dca6d07ea7"}, {"title": "宋史·巻二百六十七", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/18e8cdf6c086e5a20bcb7a3069fc49c3f0352eb3/content/books/zizhi-tongjian/vol-294/year-0959/part-04/sources/library/songshi-267-zhangji-posthumous-title/source.txt", "note": "《宋史》巻二百六十七，段落 songshi-9c6e46fee832-p058678；EPUB电子本，纸本及异文待核", "id": "da23e907-0169-526d-b16e-f1fdab658a49"}, {"title": "宋史·巻二百七十二", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/18e8cdf6c086e5a20bcb7a3069fc49c3f0352eb3/content/books/zizhi-tongjian/vol-294/year-0959/part-04/sources/library/songshi-272-jinghanru-early/source.txt", "note": "《宋史》巻二百七十二，段落 songshi-9c6e46fee832-p059022；EPUB电子本，纸本及异文待核", "id": "5de71480-819a-57be-bdbd-579c924943c7"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/18e8cdf6c086e5a20bcb7a3069fc49c3f0352eb3/content/books/zizhi-tongjian/vol-294/year-0959/part-04/sources/library/tongjian-294-959-final-affairs/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003495；电子底本待考，分段待核", "id": "7638ccc2-16f3-54ee-824b-7cf3db40c7ec"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/18e8cdf6c086e5a20bcb7a3069fc49c3f0352eb3/content/books/zizhi-tongjian/vol-294/year-0959/part-04/sources/library/tongjian-294-final-body-memorial/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003496；电子底本待考，分段待核", "id": "5f4f7618-755c-5d2e-98e5-01d80bb5ec61"}, {"title": "新五代史·卷二十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/18e8cdf6c086e5a20bcb7a3069fc49c3f0352eb3/content/books/zizhi-tongjian/vol-294/year-0959/part-04/sources/library/xinwudaishi-20-seven-sons/source.txt", "note": "《新五代史》卷二十，段落 xin-wudaishi-b08f244b9241-p000667；EPUB电子本，纸本及异文待核", "id": "86429d65-4736-516a-93d0-b0fbbad043be"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/18e8cdf6c086e5a20bcb7a3069fc49c3f0352eb3/content/books/zizhi-tongjian/vol-294/year-0959/part-04/sources/library/xinwudaishi-62-currency/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003157；EPUB电子本，纸本及异文待核", "id": "a278d4e0-2c14-5bac-ba34-920b528830d8"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/18e8cdf6c086e5a20bcb7a3069fc49c3f0352eb3/content/books/zizhi-tongjian/vol-294/year-0959/part-04/sources/library/xinwudaishi-62-succession-capital/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003158；EPUB电子本，纸本及异文待核", "id": "34ed045d-2bde-5daf-90ce-f1c1b687b297"}, {"title": "新五代史·卷六十五", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/18e8cdf6c086e5a20bcb7a3069fc49c3f0352eb3/content/books/zizhi-tongjian/vol-294/year-0959/part-04/sources/library/xinwudaishi-65-zhongyunzhang-case/source.txt", "note": "《新五代史》卷六十五，段落 xin-wudaishi-b08f244b9241-p003293；EPUB电子本，纸本及异文待核", "id": "098c66b9-339f-515a-8010-8fa3f14b2750"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1077369385e2f45f53fcb123c439df6b8e4a0f85/content/books/zizhi-tongjian/vol-294/year-0959/part-03/sources/library/tongjian-294-959-court-succession/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003494；电子底本待考，分段待核", "id": "fecef7aa-df7f-5383-beea-ca1bfea27b41"}, {"title": "旧五代史·卷一百十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/052a8074ed5386bf0e6e93afa0652e5c64213b7e/content/books/zizhi-tongjian/vol-294/year-0959/part-02/sources/library/jiuwudaishi-119-june-959/source.txt", "note": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002801；EPUB电子本，纸本及异文待核", "id": "e90d7a2f-c277-5e4e-82d8-8c92e03d9797"}, {"title": "新五代史·卷十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1077369385e2f45f53fcb123c439df6b8e4a0f85/content/books/zizhi-tongjian/vol-294/year-0959/part-03/sources/library/xinwudaishi-12-gongdi-accession/source.txt", "note": "《新五代史》卷十二，段落 xin-wudaishi-b08f244b9241-p000383；EPUB电子本，纸本及异文待核", "id": "06101707-d3d2-5a5a-ab97-fc8cdebd9247"}, {"title": "新五代史·卷二十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/1077369385e2f45f53fcb123c439df6b8e4a0f85/content/books/zizhi-tongjian/vol-294/year-0959/part-03/sources/library/xinwudaishi-20-sons-959/source.txt", "note": "《新五代史》卷二十，段落 xin-wudaishi-b08f244b9241-p000669；EPUB电子本，纸本及异文待核", "id": "33fec61f-8a07-5919-8420-afec0dd857d2"}, {"title": "新五代史·卷65·南汉世家第五·刘鋹初名", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe4b4148ad7d1e2ee8fc2e5d5c0cfad4d17a33c/content/books/zizhi-tongjian/vol-291/year-0953/part-04/sources/library/xinwudaishi-65-liuchang-name/source.txt", "note": "《新五代史》卷65·南汉世家第五·刘鋹初名，段落 xin-wudaishi-b08f244b9241-p003292；已核上下文及传主，纸本及异文待核。", "id": "b83c5ed1-82a1-536c-b380-2836d8cfbb26"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "唐镐", "aliases": ["唐鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐枢密副使、给事中，959年支持李璟经营洪州为南都。与钟谟因李德明之死的旧事有嫌隙，后向李璟指控钟谟、张峦疑有异谋。《新五代史》相关段称枢密使，职名详略保留，生卒年未核。", "biography": null, "status": "draft", "id": "2ebff905-0265-51cd-b3ae-c2ab42553456"}, {"name": "钟谟", "aliases": ["鍾謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "会稽人，南唐吏部郎中。949年条下与李德明一起参与国政，史书称两人以辩才聪慧受到李璟宠信。与后文同名外交官的进一步经历按年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ee7c4ab6-a8d3-5f0a-8b05-ede060c3934c"}, {"name": "韩熙载", "aliases": ["韓熙載", "熙载"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：韩熙载，韩叔嗣之子、拟奔吴者。", "biography": null, "status": "draft", "id": "83af8c00-ec9d-5693-9e26-56dc1a5a6a88"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "李昊", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光三年条所见人物：李昊。", "biography": null, "status": "draft", "id": "ecf7855b-2568-576c-b0b9-58e6b1f120fa"}, {"name": "李起（后蜀右补阙）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "邛州人，后蜀右补阙。959年八月反对宰相李昊兼领武信节度使，史书称其性格直率。与其他时代同名李起区分，生卒年未载。", "biography": null, "status": "draft", "id": "7a5f6f8b-cc5f-5ee3-95fe-026b76bc7812"}, {"name": "宗让（柴荣子）", "aliases": ["宗让", "宗讓", "熙让", "熙讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "柴荣之子。959年六月授左骁卫上将军，通鉴封号作燕王，新旧五代史作燕国公。新五代史又载八月更名熙让、封曹王，沿同一主体保存别名，改名事件留到相应连续段落。生卒年未载。", "biography": null, "status": "draft", "id": "2017dec1-e62f-59a1-992b-3f995a2ca6d6"}, {"name": "熙谨（柴荣子）", "aliases": ["熙谨", "熙謹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "柴荣之子、宗训的弟弟。959年八月庚寅封纪王。《新五代史》列于世宗诸子，并称母亲身份不详。生卒年此处未核。", "biography": null, "status": "draft", "id": "ee641984-7ab8-5607-9122-88b1031cc26c"}, {"name": "熙诲（柴荣子）", "aliases": ["熙诲", "熙誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "柴荣之子、宗训的弟弟。959年八月庚寅封蕲王。《新五代史》列于世宗诸子，并称母亲身份不详。生卒年未载。", "biography": null, "status": "draft", "id": "8b36c4b8-d471-50d9-801d-4dee73a3743f"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "李弘冀", "aliases": ["弘冀", "李冀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李璟的长子。943年七月条下被立为南昌王。姓名在《资治通鉴》作弘冀，《新五代史》同一册封作冀；沿用同一主体，不因姓名省写再建李冀。生卒年尚未核。", "biography": null, "status": "draft", "id": "e4027731-d3e9-5cd1-8c58-d504f38025da"}, {"name": "张洎", "aliases": ["張洎"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "全椒人，南唐官员。959年九月以太子德应重孝敬为由，反对给李弘冀谥武宣，促成改谥文献。通鉴记由句容尉擢上元尉，宋史则合叙解褐上元尉、改谥后擢监察御史，职序差别保留。生卒年未核。", "biography": null, "status": "draft", "id": "db1617d3-750e-53ed-8e79-996dc156d45e"}, {"name": "阎式", "aliases": ["閻式"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员，钟谟所交好的人。李弘冀主持朝政时，钟谟求兼东宫官未获准，转而推荐阎式任司议郎、掌百司关启。具体任命日及生卒年未载。", "biography": null, "status": "draft", "id": "2820bfec-a2ae-5c95-86fc-9ed48bf360c0"}, {"name": "张峦", "aliases": ["張巒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐黑云指挥使。951年十二月任知全州，防备南汉。《新五代史》保大十年另记他出兵争桂管失败，时序另保留。生卒年未载。", "biography": null, "status": "draft", "id": "660a73c2-c72e-5e9c-a384-6c53eff0c794"}, {"name": "李从嘉", "aliases": ["李從嘉", "从嘉", "李煜", "李后主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李璟第六子，李弘冀的弟弟，当时封安定公，后来名李煜。《宋史》明确本名从嘉。958年弘冀掌东宫后，他因畏惧哥哥而不参与政务，以读书自娱。生卒年本批未核。", "biography": null, "status": "draft", "id": "fa94de5d-24bb-5819-be0e-e4ebb6fcbaf2"}, {"name": "刘继兴", "aliases": ["劉繼興", "刘鋹", "劉鋹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉刘晟之子，953年封卫王。《新五代史》明确记刘鋹初名继兴，保留同人别名；当时尚未即位，生卒年暂未核定。", "biography": null, "status": "draft", "id": "28c53941-c17f-5791-806a-6e3c36a944c3"}, {"name": "钟允章", "aliases": ["鍾允章"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉知制诰。948年奉刘晟之命到楚国求婚，马希广拒绝；返回后向刘晟说明马氏兄弟正在相争。《新五代史》还记他的工部郎中职务。婚姻双方未具名，生卒年未据本次原文确定。", "biography": null, "status": "draft", "id": "e31bf81a-3c5e-51e7-87a1-0c580cdea1e7"}, {"name": "许彦真", "aliases": ["許彥真"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉内侍监。959年郊祀前指控钟允章谋反，又追加指控其二子，导致父子被捕并杀害。指控与事实分开，生卒年未核。", "biography": null, "status": "draft", "id": "a9191130-e3c2-5355-8c7a-9e760d3e2b55"}, {"name": "龚澄枢", "aliases": ["龔澄樞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "番禺人，南汉内给事。956年林延遇病重时推荐其代任，刘弘熙随后任其知承宣院及内侍省。生卒年及后续权势经历待按年代补录。", "biography": null, "status": "draft", "id": "aa5dc218-7d09-572f-93d5-41b8a0cb2575"}, {"name": "李托", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "封州人，南汉内侍监。959年与龚澄枢等支持许彦真对钟允章的指控。原文没有证明钟允章确曾谋反，生卒年未核。", "biography": null, "status": "draft", "id": "a5a8bc2c-32fe-5a25-b364-dd25710275d4"}, {"name": "薛用丕", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉礼部尚书，与钟允章交好。959年奉命参与审理钟允章案，听其诉冤并请求以后向幼子说明。是否实际完成该托付原文未载，生卒年未核。", "biography": null, "status": "draft", "id": "21145a0d-aed3-5507-a5e2-0859760a1459"}, {"name": "钟邕", "aliases": ["鍾邕"], "era": "五代十国", "birth_year": null, "death_year": 959, "description": "钟允章的幼子，史书以邕记名。959年随父被许彦真追加指控，后与父及另一子钟昌一同被杀。出生年未载。", "biography": null, "status": "draft", "id": "96f27012-8d20-5308-8292-12ba03b8c818"}, {"name": "钟昌", "aliases": ["鍾昌"], "era": "五代十国", "birth_year": null, "death_year": 959, "description": "钟允章的幼子，史书以昌记名。959年随父被许彦真追加指控，后与父及另一子钟邕一同被杀。出生年未载。", "biography": null, "status": "draft", "id": "32032c59-a253-5356-b1ae-ed0ca0a4f3d1"}, {"name": "何敬洙", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐天威都虞候。945年李璟任他为建州行营招讨马步都指挥使，与祖全恩、姚凤率数千兵增援查文徽，攻建州。生卒年本段未载。", "biography": null, "status": "draft", "id": "775d369d-2375-51d0-bcd1-b59c3a78d7c1"}, {"name": "陈继善", "aliases": ["陳繼善"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐兵部尚书。959年洪州改南昌府、建南都时任南昌尹，生卒年未载。", "biography": null, "status": "draft", "id": "b77c4e87-a3b7-5570-8140-4400d3653b2c"}, {"name": "徐及甫", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀都官郎中。后周攻秦凤时结党，拟拥立前蜀高祖之孙王令仪，因周军退而停止。959年事发被捕时自杀，早先谋划的具体年日未在本段独载。", "biography": null, "status": "draft", "id": "4a147af9-1c6a-5441-8853-b093b3730bb2"}, {"name": "王令仪", "aliases": ["王令儀"], "era": "五代十国", "birth_year": null, "death_year": 959, "description": "前蜀高祖王建的孙子，后蜀少府少监。徐及甫曾拟拥立他，是否主动参与原文未明。959年十二月甲午被赐死，生年未载。", "biography": null, "status": "draft", "id": "71100191-5e2a-5784-9efb-621333e1c8c1"}, {"name": "王建", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“蜀王与晋王讨论讨梁及称帝”中为致书提议者。", "biography": null, "status": "draft", "id": "b02193d6-1c17-5154-bb7c-3295ed8dbbec"}, {"name": "窦仪", "aliases": ["竇儀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟州人，后晋天平军观察判官。944年正月奉颜衎命向朝廷奏报周儒降契丹、引兵渡河及蔡行遇被俘，并向景延广说明与杨光远会合的危险。生卒年本批未核。", "biography": null, "status": "draft", "id": "9d318328-3904-5714-a390-ea527c3e9fd9"}, {"name": "耶律璟", "aliases": ["耶律述律", "述律王", "寿安王", "壽安王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律德光的长子，小字述律，封寿安王。《资治通鉴》949年条称述律王，记他派骑兵带走石重贵的宠姬赵氏、聂氏；《辽史》穆宗纪可核对姓名和亲支。949年时仍以述律王身份见于记载。", "biography": null, "status": "draft", "id": "81fb2030-5792-5006-be3c-0909be18feec"}, {"name": "契丹使者（耶律璟舅，959年）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 959, "description": "耶律璟的舅父，姓名未载。959年受遣出使南唐，在清风驿夜宴时遇刺身亡。荆罕儒募刺客行刺，原文未说明刺客姓名，生年未载。", "biography": null, "status": "draft", "id": "c6686d8c-8d91-5bbd-a562-2625e89b41ce"}, {"name": "荆罕儒", "aliases": ["荊罕儒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冀州信都人，后周泰州团练使。959年募刺客杀死赴南唐的契丹使者，该使者是耶律璟的舅父。《宋史》记其父名基、任王屋令，并载其从赵延寿、参加高平及淮南战事等经历。生卒年此处未核。", "biography": null, "status": "draft", "id": "417bc95d-ddee-585a-ba66-7adaddeb8752"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
