SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "李璟议迁洪州，唐镐支持，命经营豫章为都城。", "citation": "卷294·显德五年（959年七月至十二月及相关追述）·zztj-v294-y0959-p033·原文件第101行", "note": "原文：唐主以金陵去周境才隔一水，洪州险固居上游，集群臣议徙都之。群臣多不欲徙，惟枢密副使、给事中唐镐劝之，乃命经营豫章为都城之制。；核对说明：本段为筹划和建设命令，不写成李璟已经在959年迁居洪州。", "status": "draft", "id": "180b93dd-ef87-5f54-bd7b-8d1d82198917", "subject_id": "96cf7754-ce87-5a26-bf41-76ddabadd86d", "source_id": "fecef7aa-df7f-5383-beea-ca1bfea27b41"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "959年七月条所记，具体议论及命令日未载", "citation": "卷294·显德五年（959年七月至十二月及相关追述）·zztj-v294-y0959-p033·原文件第101行", "note": "原文：唐主以金陵去周境才隔一水，洪州险固居上游，集群臣议徙都之。群臣多不欲徙，惟枢密副使、给事中唐镐劝之，乃命经营豫章为都城之制。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "b9adfab7-712f-5b70-a6ab-6876aa1d7740", "subject_id": "96cf7754-ce87-5a26-bf41-76ddabadd86d", "source_id": "fecef7aa-df7f-5383-beea-ca1bfea27b41"}, {"subject_table": "person", "field_path": "description", "claim_text": "李璟：召群臣议迁都并命经营豫章。", "citation": "卷294·显德五年（959年七月至十二月及相关追述）·zztj-v294-y0959-p033·原文件第101行", "note": "原文：唐主以金陵去周境才隔一水，洪州险固居上游，集群臣议徙都之。群臣多不欲徙，惟枢密副使、给事中唐镐劝之，乃命经营豫章为都城之制。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "500a13d9-ce39-5994-ab74-ccd8de68ecd6", "subject_id": "6bf72971-88c3-5187-8f25-98cde2a9554a", "source_id": "fecef7aa-df7f-5383-beea-ca1bfea27b41"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李璟：召群臣议迁都并命经营豫章。", "citation": "卷294·显德五年（959年七月至十二月及相关追述）·zztj-v294-y0959-p033·原文件第101行", "note": "原文：唐主以金陵去周境才隔一水，洪州险固居上游，集群臣议徙都之。群臣多不欲徙，惟枢密副使、给事中唐镐劝之，乃命经营豫章为都城之制。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "7f7fd76f-f96e-591c-9a41-faab0f8c8e94", "subject_id": "99709a29-efc9-57b5-b104-4863a7e3eb73", "source_id": "fecef7aa-df7f-5383-beea-ca1bfea27b41"}, {"subject_table": "person", "field_path": "description", "claim_text": "唐镐：支持在洪州经营新都。", "citation": "卷294·显德五年（959年七月至十二月及相关追述）·zztj-v294-y0959-p033·原文件第101行", "note": "原文：唐主以金陵去周境才隔一水，洪州险固居上游，集群臣议徙都之。群臣多不欲徙，惟枢密副使、给事中唐镐劝之，乃命经营豫章为都城之制。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "54e72251-67d1-5186-b9ef-191d3dae21b7", "subject_id": "2ebff905-0265-51cd-b3ae-c2ab42553456", "source_id": "fecef7aa-df7f-5383-beea-ca1bfea27b41"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "唐镐：支持在洪州经营新都。", "citation": "卷294·显德五年（959年七月至十二月及相关追述）·zztj-v294-y0959-p033·原文件第101行", "note": "原文：唐主以金陵去周境才隔一水，洪州险固居上游，集群臣议徙都之。群臣多不欲徙，惟枢密副使、给事中唐镐劝之，乃命经营豫章为都城之制。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "890a2c7c-bbde-518d-9631-b9f9c78bf2f1", "subject_id": "82ee1c0f-3960-5852-baf1-b9d3f8a13e9a", "source_id": "fecef7aa-df7f-5383-beea-ca1bfea27b41"}, {"subject_table": "event", "field_path": "description", "claim_text": "《新五代史》也记唐镐支持迁洪州，并明确建隆二年李璟才迁南都。", "citation": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003158；EPUB电子本，纸本及异文待核", "note": "原文：謀遷其都于洪州，羣臣皆不欲遷，惟樞密使唐鎬贊之，乃升洪州為南昌，建南都。建隆二年，留太子從嘉監國，景遷于南都。；核对说明：建隆二年为961年，筹划、建南都与实际迁居分别记录；本段唐镐《资治通鉴》枢密副使、《新五代史》枢密使保留职名差别。", "status": "draft", "id": "25e5899b-1534-5a3b-beaa-03fdb2145ad2", "subject_id": "96cf7754-ce87-5a26-bf41-76ddabadd86d", "source_id": "34ed045d-2bde-5daf-90ce-f1c1b687b297"}, {"subject_table": "event", "field_path": "description", "claim_text": "《资治通鉴》称南唐战后贡输使府库和货币承压。", "citation": "卷294·显德五年（959年七月至十二月及相关追述）·zztj-v294-y0959-p034·原文件第102行", "note": "原文：唐自淮上用兵及割江北，臣事于周，岁时贡献，府藏空竭，钱益少，物价腾贵。；核对说明：府藏空竭、钱少物贵为史家对财政的概述，未给可核现代价格指数，不补精确涨幅。", "status": "draft", "id": "fd3fc098-8e27-51fe-b0a5-08a7a19aa984", "subject_id": "996f3e12-0f10-5d63-b781-d4a55c252419", "source_id": "fecef7aa-df7f-5383-beea-ca1bfea27b41"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "南唐淮南战事、割江北及臣周后的概述，所述不限单日", "citation": "卷294·显德五年（959年七月至十二月及相关追述）·zztj-v294-y0959-p034·原文件第102行", "note": "原文：唐自淮上用兵及割江北，臣事于周，岁时贡献，府藏空竭，钱益少，物价腾贵。；核对说明：按《资治通鉴》及对应补证纪时；